function validate([n, m, k, source, dest]) {
  if (!Number.isInteger(n) || n < 2 || n > 1e9) return 'n is an integer from 2 to 10^9.';
  if (!Number.isInteger(m) || m < 2 || m > 1e9) return 'm is an integer from 2 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > 100000) return 'k is an integer from 1 to 10^5.';
  for (const cell of [source, dest]) {
    if (!Array.isArray(cell) || cell.length !== 2) return 'source and dest are [row, column] pairs.';
    if (!Number.isInteger(cell[0]) || cell[0] < 1 || cell[0] > n) return 'A row number is between 1 and n.';
    if (!Number.isInteger(cell[1]) || cell[1] < 1 || cell[1] > m) return 'A column number is between 1 and m.';
  }
  return null;
}

