function numberOfWays(n, m, k, source, dest) {
  const MOD = 1000000007n;
  const rows = BigInt(n);
  const cols = BigInt(m);
  const sameRow = source[0] === dest[0];
  const sameCol = source[1] === dest[1];

  let atDest = sameRow && sameCol ? 1n : 0n;
  let inRow = sameRow && !sameCol ? 1n : 0n;
  let inCol = !sameRow && sameCol ? 1n : 0n;
  let other = !sameRow && !sameCol ? 1n : 0n;

  for (let step = 0; step < k; step++) {
    const nextDest = (inRow + inCol) % MOD;
    const nextRow = (atDest * (cols - 1n) + inRow * (cols - 2n) + other) % MOD;
    const nextCol = (atDest * (rows - 1n) + inCol * (rows - 2n) + other) % MOD;
    const nextOther = (inRow * (rows - 1n) + inCol * (cols - 1n) + other * (rows + cols - 4n)) % MOD;
    atDest = nextDest;
    inRow = nextRow;
    inCol = nextCol;
    other = nextOther;
  }
  return Number(atDest);
}

