function numberOfWays(n, m, k, source, dest) {
  // A move changes exactly one coordinate, so the row walk and the column walk are independent:
  // choose which j of the k moves change the row, then walk K_n for j steps and K_m for k - j steps.
  const P = 1000000007n;
  const walks = (size, from, to) => {
    const out = [];
    let hit = from === to ? 1n : 0n, miss = 1n - hit;
    for (let t = 0; t <= k; t++) {
      out.push(hit);
      [hit, miss] = [miss % P, (hit * BigInt(size - 1) + miss * BigInt(size - 2)) % P];
    }
    return out;
  };
  const rowWalks = walks(n, source[0], dest[0]);
  const colWalks = walks(m, source[1], dest[1]);
  let total = 0n, choose = 1n;
  for (let j = 0; j <= k; j++) {
    total = (total + (choose % P) * rowWalks[j] % P * colWalks[k - j]) % P;
    choose = choose * BigInt(k - j) / BigInt(j + 1);
  }
  return Number(total);
}

