function generate(rand, size) {
  const side = () => {
    if (size === 'large') return rand() < 0.2 ? 2 + Math.floor(rand() * 3) : 1e9 - Math.floor(rand() * 1e8);
    return rand() < 0.2 ? 1e9 - Math.floor(rand() * 10) : 2 + Math.floor(rand() * 4);
  };
  const n = side();
  const m = side();
  const k = size === 'large' ? 100000 - Math.floor(rand() * 1000) : 1 + Math.floor(rand() * 8);
  const pick = (limit) => 1 + Math.floor(rand() * limit);
  const source = [pick(n), pick(m)];
  const dest = [rand() < 0.4 ? source[0] : pick(n), rand() < 0.4 ? source[1] : pick(m)];
  return [n, m, k, source, dest];
}
